#!/usr/bin/env python3
"""Generate a compact BFRT-shell program matching the supplied experiment tables."""
import argparse
from pathlib import Path

PROGRAMS = {"pallas": "pallas", "opt-pallas": "pallas_opt"}


def render(variant, configure_ports=False, clear_table=False):
    """Return standalone Python to execute inside the SDE BFRT shell."""
    if variant not in PROGRAMS:
        raise ValueError("Unknown variant: " + variant)
    table = "division_table" if variant == "pallas" else "exp_table"
    lines = [
        '# Generated by scripts/generate_tables.py; execute in the BFRT shell.',
        'import math',
        'p4 = bfrt.' + PROGRAMS[variant] + '.pipe',
    ]
    if configure_ports:
        lines += ['''# Original testbed port setup; confirm cage mapping before execution.
for cage in (1, 5):
    port = bfrt.port.port_hdl_info.get(
        CONN_ID=cage, CHNL_ID=0, print_ents=False).data[b'$DEV_PORT']
    bfrt.port.port.add(
        DEV_PORT=port, SPEED="BF_SPEED_100G", FEC="BF_FEC_TYP_NONE",
        AUTO_NEGOTIATION="PM_AN_FORCE_DISABLE", PORT_ENABLE=True)''']
    lines.append('table = p4.Ingress.' + table)
    if clear_table:
        lines.append('table.clear(batch=True)')
    lines.append('entry_count = 0')
    if variant == 'pallas':
        lines.append('''for divisor in range(1, 2048):
    table.add_with_set_division_action(
        divided_value=divisor, f_action=2048 // divisor)
    entry_count += 1''')
    else:
        lines.append('''# Preserve the uploaded generator settings, including its sparse coverage.
# The paper uses alpha=0.11 and ternary compression; this snapshot does not.
for persistence in range(1, 1400):
    for gap in range(persistence + 1):
        threshold = int((1 - math.exp(-0.13 * (gap / persistence))) * 2048)
        if threshold > 150:
            table.add_with_set_exp_action(
                gap=gap, persistence_count=persistence, f_action=threshold)
            entry_count += 1''')
    lines += ['bfrt.complete_operations()', 'print("Programmed", entry_count, "entries")', '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--variant', choices=PROGRAMS, required=True)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--configure-ports', action='store_true',
                        help='Include original cages 1/5, lane 0, 100G configuration')
    parser.add_argument('--clear-table', action='store_true',
                        help='Clear only the selected probability table before loading')
    args = parser.parse_args()
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(render(args.variant, args.configure_ports, args.clear_table))
    print('Written:', args.output)


if __name__ == '__main__':
    main()
